import json
from pathlib import Path
K='https://learn.microsoft.com/en-us/kusto/query/'
S='https://learn.microsoft.com/en-us/azure/sentinel/'
D='https://learn.microsoft.com/en-us/defender-xdr/'
def question(id,type,stem,options,answer,explanations,source,context,code=None):
 q=dict(id=id,type=type,difficulty='Analyze',stem=stem,options=options,answer=answer,explanations=explanations,source=source,context=context,takeaway=explanations[answer[0]])
 if code:q['code']=code
 return q
manage=json.load(open('work/content/manage.json'))
c1='''CASE 1 — REDWOOD RETAIL\n\nRedwood has connected its Sentinel workspace to the Defender portal. Its firewall emits correctly formatted CEF through local4 at informational severity to a supported Linux forwarder. The forwarder receives the messages, but its DCR currently collects local5 at error and above.\n\nThe SOC wants a scheduled detector evaluated every five minutes. The source can arrive 20 minutes late; the approved design is a 45-minute event-time lookback. Matching alerts must include the source IP as an entity. The SOC also wants matching new high-severity incidents assigned and tagged without calling an external service.\n\nA tier-one analyst may assign and close incidents but may not edit analytics rules. A separate engineer owns detection configuration. The SOC must validate data collection and representative detection results before declaring coverage. Assume supported connectors and required licensing are available.'''
qs=[
question('redwood-case-q1','single','Which change addresses the first proven break in Redwood’s firewall collection path?',['Change the DCR to include local4 informational and required severities.','Increase the analytics rule frequency while leaving the DCR unchanged.','Convert the workbook into a playbook.','Wait for XDR incident correlation to create the missing raw events.'],[0],['The forwarder has received the data, but the collection facility and threshold do not match the emitted messages.','Scheduling cannot recover messages excluded by the collection filter.','A visualization or workflow change does not fix the DCR mismatch.','Correlation cannot synthesize telemetry discarded before ingestion.'],S+'connect-cef-syslog-ama',c1),
question('redwood-case-q2','multi','Which TWO settings directly express the approved detector behavior and investigation context?',['Run every five minutes with a 45-minute event-time lookback.','Map the returned source-IP field to the appropriate IP entity identifier.','Look back only five minutes because that is also the run frequency.','Rely on the workbook time picker to set the rule’s production lookback.'],[0,1],['Frequency controls how often the query runs; the approved larger lookback accommodates the stated late data.','Entity mapping lets investigation features recognize the IP represented in query output.','This would miss the stated 20-minute-late events and contradict the approved design.','A workbook filter does not configure an analytics rule’s production query interval.'],S+'scheduled-rules-overview',c1),
question('redwood-case-q3','single','The requested assignment and tag changes need no external API. Which implementation has the appropriate scope?',['An automation rule with conditions and native incident actions.','A workbook containing two charts.','A new threat intelligence feed.','A live-response session on every firewall.'],[0],['Automation rules can match incident conditions and apply native assignment and tagging actions.','Charts display data rather than implement these incident actions.','Intelligence ingestion does not perform incident ownership and tagging workflow.','Endpoint response sessions are unrelated to Sentinel incident assignment.'],S+'automate-incident-handling-with-automation-rules',c1),
question('redwood-case-q4','single','Which built-in Sentinel role best fits the tier-one analyst’s stated duties, assuming no broader inherited role?',['Microsoft Sentinel Reader','Microsoft Sentinel Responder','Microsoft Sentinel Contributor','Subscription Owner'],[1],['Reader can view but does not supply the required incident-management authority.','Responder supports incident management without the detection-editing authority of Contributor.','Contributor is broader than the incident duties specified.','Owner is far broader than the required Sentinel incident workflow.'],S+'roles',c1)]
next(l for l in manage if l['id']=='sentinel-analytics')['questions']+=qs
Path('work/content/manage.json').write_text(json.dumps(manage,ensure_ascii=False,indent=2))
respond=json.load(open('work/content/respond.json'))
c2='''CASE 2 — NORTHSTAR LABS\n\nThe CFO reports a suspicious message. Defender for Office 365 shows it was delivered, and investigators have its NetworkMessageId and the recipient address. EmailUrlInfo contains a suspicious domain; there is not yet verified click evidence.\n\nMinutes later the CFO’s onboarded workstation starts an unusual script and continues making suspicious outbound connections while files are being modified. Entra sign-in evidence also supports theft of an authenticated cloud session. There are other recipients of related messages, but the full scope is unknown.\n\nNorthstar requires supported containment that preserves the endpoint’s Defender service connection. The analyst must investigate message recipients, endpoint execution, and identity access as connected workstreams. An incident is not considered resolved until the team verifies response actions, checks for persistence, and documents scope and residual risk. Assume the relevant services are deployed and the analyst has the required permissions.'''
qs=[
question('northstar-case-q1','single','Which immediate endpoint action best matches the stated containment requirement?',['Offboard the workstation from Defender.','Isolate the onboarded device using the supported Defender action.','Close the alert so the script stops.','Delete all timeline records before investigating.'],[1],['Offboarding removes the monitoring relationship and does not provide the requested supported containment.','Device isolation restricts network communication while preserving the supported Defender connection.','Changing an alert status is not an endpoint containment action.','Removing evidence would neither meet the containment requirement nor preserve investigation context.'], 'https://learn.microsoft.com/en-us/defender-endpoint/respond-machine-alerts',c2),
question('northstar-case-q2','multi','Which TWO investigative conclusions are justified by the case evidence?',['A URL in EmailUrlInfo proves the CFO clicked it successfully.','Investigate Safe Links click telemetry and endpoint connection evidence to test the click hypothesis.','Scope the related message recipients and inspect the compromised identity’s session and persistence activity.','A delivered email proves every recipient’s device is compromised.'],[1,2],['URL presence establishes content, not user interaction or successful navigation.','These sources can test the unproven user-click and device-contact portions of the chain.','The evidence spans email, endpoint, and identity; scope and persistence require investigation across them.','Delivery alone does not establish execution or compromise for every recipient.'],D+'advanced-hunting-urlclickevents-table',c2),
question('northstar-case-q3','single','The workstation is isolated and malicious messages have been removed. Evidence still supports a stolen cloud session. What response remains necessary?',['Declare recovery because device isolation stops all cloud access.','Address identity access and sessions, then verify the resulting containment and persistence state.','Only lower the incident severity.','Assume deleting email automatically invalidates every authentication token.'],[1],['Endpoint isolation is not equivalent to revoking an attacker’s cloud session.','Identity containment and validation are still required for the separately evidenced access path.','Severity is a triage attribute, not account remediation.','Mail removal does not itself invalidate authenticated sessions.'],'https://learn.microsoft.com/en-us/entra/identity/users/users-revoke-access',c2),
question('northstar-case-q4','order','After urgent containment, arrange Northstar’s evidence-based path to closing the incident.',['Document disposition, completed actions, remaining risk, and accountable follow-up before closure.','Investigate the affected entities and establish scope and persistence.','Verify that executed response actions succeeded and validate recovery.','Remediate the validated persistence and affected access paths through the appropriate products.'],[1,3,2,0],['Closure follows a documented explanation of what was done and what remains.','Establish the actual attack scope and persistence before selecting full remediation.','Success must be checked rather than inferred from a submitted action.','Apply remediation to the confirmed access paths and persistence.'],D+'investigate-incidents',c2)]
next(l for l in respond if l['id']=='incident-triage')['questions']+=qs
Path('work/content/respond.json').write_text(json.dumps(respond,ensure_ascii=False,indent=2))
hunt=json.load(open('work/content/hunt.json'))
c3='''CASE 3 — TAILSPIN HUNT\n\nTailspin is testing the hypothesis that users with repeated failed Entra sign-ins also start suspicious PowerShell processes on endpoints. SigninLogs contains TimeGenerated, UserId, and ResultType; "0" means a successful sign-in for this exercise. DeviceProcessEvents contains Timestamp, AccountObjectId, DeviceId, FileName, and ProcessCommandLine. In this dataset, AccountObjectId and UserId are populated with matching Entra object identifiers.\n\nThe hunt defines a suspicious user as one with at least ten failed sign-in records in the last hour. For each matching user, investigators want every matching PowerShell process event from the same hour, even if several events share the same user identifier. They must retain device and command-line evidence. A match tests the stated hypothesis; it does not by itself prove that the failed sign-ins caused the process execution.'''
qs=[
question('tailspin-case-q1','single','Which definition identifies exactly the failed-sign-in user population specified by Tailspin?',['SigninLogs | where TimeGenerated > ago(1h) | where ResultType != "0" | summarize Failures=count() by UserId | where Failures >= 10','SigninLogs | summarize count() by ResultType | where count_ >= 10','SigninLogs | where ResultType == "0" | summarize Failures=count() by UserId','DeviceProcessEvents | summarize Failures=count() by DeviceId'],[0],['This applies the correct time, failure predicate, per-user grouping, and threshold in the right order.','This omits the required time and per-user definition and combines unrelated users.','This counts successful sign-ins and omits the stated recent window.','Endpoint process records do not supply the required Entra failed-sign-in population.'],K+'tutorials/use-aggregation-functions?view=azure-data-explorer',c3),
question('tailspin-case-q2','multi','You join filtered process events on the left to the suspicious-user set on the right. Choose TWO decisions that meet the case requirements.',['Use explicit kind=inner to retain every matching process-event pair.','Correlate $left.AccountObjectId == $right.UserId.','Omit the kind because innerunique always preserves every left-side event.','Correlate DeviceId to UserId because both are strings.'],[0,1],['An inner join retains all matching event pairs rather than deduplicating the left user keys.','The case explicitly establishes that these two fields contain matching Entra identifiers.','The default innerunique deduplicates left-side join keys and can discard process events.','The identifiers represent different entity types and are not interchangeable.'],K+'join-innerunique?view=microsoft-fabric',c3),
question('tailspin-case-q3','single','The join returns several PowerShell process events for a user with many failed sign-ins. What can the analyst conclude?',['The correlation establishes matching activity within the hunt’s scope, requiring validation of the attack story.','The failed sign-ins are proven to have caused each process execution.','Every PowerShell command in the tenant is now confirmed malicious.','The query has automatically created an analytics rule and incident.'],[0],['The query supports the hypothesis for investigation but does not establish causality or a malicious verdict by itself.','A matching identifier and interval do not prove causation.','The hunt does not justify a tenant-wide malicious verdict.','An ad hoc query does not automatically configure a production detector.'],S+'hunting',c3),
question('tailspin-case-q4','single','An engineer inserts `| project Timestamp, DeviceId, ProcessCommandLine` before the join and the key becomes unresolved. Which correction preserves the required correlation?',['Keep AccountObjectId through the join, then shape the final evidence output.','Remove the join key from both sides and rely on row order.','Replace the join with an unfiltered union and claim each row is correlated.','Group everything by FileName and drop all entity identifiers.'],[0],['The key must remain in the pipeline until the join consumes it; final projection can happen afterward.','Row positions do not establish an entity relationship.','Appending events is not equivalent to matching the specified users.','This loses the user and device evidence the case requires.'],K+'project-operator?view=microsoft-fabric',c3)]
next(l for l in hunt if l['id']=='kql-correlation')['questions']+=qs
Path('work/content/hunt.json').write_text(json.dumps(hunt,ensure_ascii=False,indent=2))
print('Added 3 case studies / 12 original questions')
